# Eindtoets 2 Praktijkproject BM: één nieuwe organisatie door het hele verbetertraject (week 0 = versie E2).
W = 0
P = "Verbeterproject"
PR = "Presentatie"
EIND_TITEL = "Logistiek Centrum Noordhaven"
EIND_UITLEG = ("Een tweede vaste toets met nieuwe vragen over alle weken. Je volgt de uitgifte van werkkleding en "
               "beschermingsmiddelen bij een logistiek centrum, van verbeterrichting tot overdracht.")

CASUS = ("Logistiek Centrum Noordhaven (fictief) heeft 600 medewerkers in drie ploegen, van wie een groot deel uitzendkrachten. "
         "Werkkleding en persoonlijke beschermingsmiddelen (PBM: veiligheidsschoenen, handschoenen, hesjes) haal je bij de "
         "magazijnbalie, die alleen in de dagdienst open is (8.00 tot 16.00 uur). Voor een nieuwe uitzendkracht vult de ploegleider "
         "een papieren formulier in en brengt het naar de balie; de enige baliemedewerker zoekt de maten op, laat aftekenen in een map "
         "en typt de uitgiftes 's middags over in Excel. Ploegleiders van de avond- en nachtdienst bellen de volgende ochtend. "
         "Uit de metingen van periode 1: een nieuwe uitzendkracht wacht gemiddeld 2,5 werkdagen op complete PBM, 1 op de 6 werkt "
         "de eerste dienst in eigen schoenen, 22% van de uitgiftes wordt omgeruild wegens een verkeerde maat en de baliemedewerker "
         "besteedt ruim 2 uur per dag aan zoeken en overtypen.")

OPTIES = ("Optie A: PBM-kluizen die 24 uur per dag open zijn met de personeelspas, gekoppeld aan het HR-systeem. "
          "Optie B: het uitzendbureau geeft vooraf de maten door, de balie zet per nieuwe uitzendkracht een startpakket klaar "
          "bij de ploegleider, en de balie is twee avonden per week open.")

# ---------- MC ----------
mc("ppe2-m01", W, P, "Logistiek Centrum Noordhaven. Een idee is om bij elke ploegleider een kleine voorraad hesjes en handschoenen in standaardmaten neer te leggen. Het kost weinig moeite en helpt meteen. Hoe noem je zo'n idee in de Impact/Effort-matrix, en wat is de keerzijde?",
   ["Quick win; lost vaak alleen een symptoom op",
    "Structurele verbetering; kost veel tijd en geld",
    "Quick win; maakt een structurele verbetering overbodig",
    "Tijdverspiller; levert weinig op voor veel moeite"], 0,
   "Veel impact, weinig moeite: een quick win. Quick wins geven momentum en draagvlak, maar lossen vaak alleen een symptoom op; hier blijven de wachttijd voor schoenen en de verkeerde maten bestaan. Kies daarom bewust ook een structurele verbetering. Een advies dat alleen symptomen bestrijdt, is zwak.")
mc("ppe2-m02", W, P, "Logistiek Centrum Noordhaven. Eén op de zes nieuwe uitzendkrachten werkt de eerste dienst in eigen schoenen. Bij welke facilitaire toegevoegde waarde past het oplossen hiervan het meest direct?",
   ["Risico's beheren", "Waardestijging", "Flexibiliteit", "Innovatie"], 0,
   "Werken zonder veiligheidsschoenen is een veiligheidsrisico: risico's beheren. Daarnaast spelen productiviteit (niet wachten), tevredenheid en kosten (minder omruilen) mee. Laat in je advies die meervoudige toegevoegde waarde zien en vermijd een eenzijdige focus op kostenreductie.")
mc("ppe2-m03", W, P, "Logistiek Centrum Noordhaven. Op maandagochtend beginnen vaak veertig nieuwe uitzendkrachten tegelijk, op andere dagen bijna niemand. Het uitzendbureau kan de startdagen over de week spreiden. Welk Lean-principe is dit?",
   ["Heijunka", "Jidoka", "Poka-Yoke", "Gemba"], 0,
   "Heijunka (pijler Snelheid): spreid werkdruk en pieken. Zo raakt de balie niet op één ochtend overbelast (muri). Jidoka en Poka-Yoke horen bij de pijler Kwaliteit; Gemba is de werkvloer waar het werk echt gebeurt.")
mc("ppe2-m04", W, P, "Logistiek Centrum Noordhaven. Hoe classificeer je de stap 'de baliemedewerker registreert welke PBM iemand heeft ontvangen', als het bedrijf die registratie nodig heeft om aan te tonen dat iedereen is uitgerust?",
   ["VA: de medewerker wil hiervoor betalen", "BNVA: geen klantwaarde, wel noodzakelijk", "NVA: pure verspilling, elimineren", "VA, omdat het om veiligheid gaat"], 1,
   "Registratie die nodig is maar de medewerker zelf niets oplevert, is BNVA: minimaliseren, bijvoorbeeld door bij de uitgifte te scannen in plaats van af te tekenen in een map. Het 's middags overtypen in Excel is wél NVA: dat elimineer je.")
mc("ppe2-m05", W, P, "Logistiek Centrum Noordhaven. " + OPTIES + " Wat zegt de les bij de dimensie risico?",
   ["Eenvoud is bijna altijd een deugd: B is minder risicovol",
    "De duurste optie heeft altijd het laagste risico op problemen",
    "Risico weeg je pas mee als de pilot volledig is afgerond",
    "Technologie verlaagt altijd het risico, dus kies je voor A"], 0,
   "Bij de dimensie risico vraag je: wat kan misgaan? Eenvoud is bijna altijd een deugd. Optie A hangt af van kluizen, passen en een koppeling met het HR-systeem; er kan dus meer misgaan. Technologie is een middel, geen doel.")
mc("ppe2-m06", W, P, "Logistiek Centrum Noordhaven. De baliemedewerker zegt over de nieuwe scanner bij de uitgifte: 'Daar kan ik toch helemaal niet mee overweg.' Welke aanpak van weerstand past hierbij?",
   ["Ruimte geven", "Training en geruststelling", "Tijd vrijmaken", "Waardering voor het verleden"], 1,
   "De oorzaak is twijfel ('kan ik dit wel?'), de aanpak training en geruststelling. Ruimte geven past bij verlies aan controle, tijd vrijmaken bij 'het kost eerst meer werk' en waardering voor het verleden bij gezichtsverlies. Weerstand is geen onwil, maar een voorspelbare reactie.")
mc("ppe2-m07", W, P, "Logistiek Centrum Noordhaven. In de RACI staan bij 'startpakketten klaarzetten' zowel de magazijnchef als de teamleider Facilitaire Services als A. Wat is het probleem?",
   ["Niemand voelt zich eigenaar van de activiteit", "Niemand geeft uiteindelijk de doorslag", "Er voert niemand het werk echt uit", "Er is geen probleem, twee A's geven extra zekerheid"], 1,
   "Per activiteit precies één A. Meerdere A's betekent dat niemand de doorslag geeft; geen A betekent dat niemand zich eigenaar voelt. Controleer elke rij op precies één A en minstens één R.")
mc("ppe2-m08", W, P, "Logistiek Centrum Noordhaven, FMEA-light. Een veiligheidsschoen in de verkeerde maat valt vaak pas op als de medewerker na een dienst over pijnlijke voeten klaagt. Welke detectiescore past hierbij?",
   ["Een lage score, want de fout is goed zichtbaar", "Een hoge score, want de fout blijft lang onopgemerkt", "Een lage score, want de ernst van de fout is beperkt", "Geen score, want detectie geldt alleen voor systemen"], 1,
   "Een hoge detectiescore betekent dat een fout moeilijk te ontdekken is en ongezien schade aanricht; een lage score dat hij makkelijk wordt opgemerkt. Slechte detecteerbaarheid verhoogt dus het RPN. Dit is de klassieke valkuil.")
mc("ppe2-m09", W, P, "Logistiek Centrum Noordhaven. Drie weken lang blijft het papieren formulier bestaan naast de nieuwe digitale aanvraag, zodat de balie kan terugvallen als er iets misgaat. Welke invoeringsstrategie is dit?",
   ["Pilot", "Gefaseerd", "Schaduwdraaien", "Big-bang"], 2,
   "Schaduwdraaien: oud en nieuw draaien tijdelijk naast elkaar. Let daarbij ook op datamigratie. Een pilot is klein testen in de echte omgeving, gefaseerd is stap voor stap per ploeg of afdeling, big-bang is in één keer over.")
mc("ppe2-m10", W, P, "Logistiek Centrum Noordhaven. Welk succescriterium voor de invoering is SMART?",
   ["Nieuwe uitzendkrachten krijgen hun beschermingsmiddelen voortaan een stuk sneller",
    "Binnen 8 weken heeft 95% van de nieuwe uitzendkrachten vóór de eerste dienst complete PBM",
    "De baliemedewerker ervaart duidelijk minder werkdruk door de nieuwe werkwijze",
    "Het aantal omruilingen daalt zo snel mogelijk tot een acceptabel niveau"], 1,
   "Een SMART criterium heeft een getal, een termijn en een duidelijke groep. Zonder vooraf afgesproken succescriteria wordt elke evaluatie een kwestie van gevoel. Koppel het criterium aan je KPI's en aan de klantwaarde.")
mc("ppe2-m11", W, P, "Logistiek Centrum Noordhaven. In het einddossier gaat het probleem over de wachttijd en de veiligheid van nieuwe uitzendkrachten, maar de enige KPI in het borgingsplan is de jaarlijkse uitgave aan werkkleding. Welk criterium van de einddossier-check is niet gehaald?",
   ["Volledig", "Consistent", "Toegankelijk", "Herhaalbaar"], 1,
   "Consistent: sluiten probleem, knelpunten, oplossing en plan logisch op elkaar aan? Een KPI over kosten zegt niets over wachttijd of veiligheid. Passend zou bijvoorbeeld zijn: het percentage nieuwe uitzendkrachten met complete PBM vóór de eerste dienst.")
mc("ppe2-m12", W, PR, "Logistiek Centrum Noordhaven. In je adviespresentatie laat je zien dat een nieuwe uitzendkracht gemiddeld 2,5 werkdagen wacht en dat 22% van de uitgiftes wordt omgeruild. Bij welk blok van PROA hoort dit vooral?",
   ["Probleem", "Risico", "Oorzaak", "Advies"], 1,
   "Risico (Measure) beantwoordt: wat is de omvang van het probleem? De cijfers laten die omvang zien. Probleem (Define en Measure) benoemt wat er mis is, Oorzaak (Analyze) waarom het ontstaat, en Advies (Generate, Improve en Control) wat je voorstelt, hoe je het invoert en hoe je grip houdt.")

# ---------- open ----------
op("ppe2-o1", W, P, CASUS + " Bedenk voor de longlist drie ideeën die zijn geïnspireerd op Lean: één uit de pijler Snelheid, één uit de pijler Kwaliteit en één op basis van 5S of standaardisatie. Noem bij elk idee het principe en het knelpunt dat het aanpakt.",
   "Snelheid, bijvoorbeeld: bottleneck/TOC, want de enige baliemedewerker in de dagdienst bepaalt de output; laat het uitzendbureau de maten vooraf doorgeven, zodat het zoeken vervalt. Of Heijunka: startdagen spreiden over de week. Of pull/Kanban: een tweebakkensysteem in de PBM-kast, waarbij een lege bak het signaal is om bij te vullen. Kwaliteit, bijvoorbeeld: Poka-Yoke, een digitale aanvraag die pas verstuurd kan worden als de schoenmaat is ingevuld; of stop de lijn (Jidoka): niemand begint aan een dienst zonder veiligheidsschoenen, de ploegleider regelt eerst een paar. 5S of standaardisatie: vaste, gelabelde vakken per maat (orde en netheid voorkomen fouten en variatie) of één werkinstructie voor de uitgifte. Elk idee moet een concreet knelpunt uit de casus raken: wachttijd, verkeerde maten, werken in eigen schoenen of overtypen.",
   ["Juist principe uit Snelheid met passend idee", "Juist principe uit Kwaliteit met passend idee", "5S of standaardisatie juist toegepast", "Elk idee gekoppeld aan een knelpunt uit de casus"])
op("ppe2-o2", W, P, "Logistiek Centrum Noordhaven. " + OPTIES + " Vergelijk de twee opties op de vier dimensies uit week 2 en kies een voorkeur.",
   "Haalbaarheid: B kan met bestaande middelen en een afspraak met het uitzendbureau; A vraagt kluizen, passen, budget en een koppeling met het HR-systeem. Met de 80/20-regel: pak eerst de artikelen aan die de meeste omruilingen veroorzaken. Impact: A lost ook het probleem van de avond- en nachtdienst volledig op (24 uur per dag); B verbetert vooral de start van nieuwe uitzendkrachten. Volgens de KKT-driehoek verbeter je zelden kwaliteit, kosten en tijd tegelijk: A is sneller voor iedereen maar duurder. Risico: B is eenvoudiger; bij A kan de koppeling of de pas falen, met medewerkers zonder schoenen als gevolg. Eenvoud is bijna altijd een deugd. Aansluiting op de context: past het bij systemen en cultuur? Als het HR-systeem uitzendkrachten pas laat registreert, sluit A slecht aan. Voorkeur, bijvoorbeeld: B nu invoeren, A eventueel later onderzoeken. Elke goed onderbouwde keuze is mogelijk.",
   ["Haalbaarheid vergeleken", "Impact vergeleken, met KKT of 80/20", "Risico vergeleken", "Context vergeleken en keuze onderbouwd"])
op("ppe2-o3", W, P, "Logistiek Centrum Noordhaven kiest voor optie B. Breng de stakeholders in kaart (let op het rimpeleffect), plaats vier van hen in de belang-invloed-grid met de bijbehorende aanpak, en benoem bij twee groepen de verwachte weerstand, de oorzaak en je aanpak.",
   "Stakeholders: directeur operations (sponsor), teamleider Facilitaire Services (proceseigenaar), baliemedewerker en ploegleiders (uitvoerders), nieuwe uitzendkrachten (gebruikers), en via het rimpeleffect ook het uitzendbureau (moet maten doorgeven), de preventiemedewerker, HR en de leverancier van werkkleding. Grid, bijvoorbeeld: directeur operations veel invloed en veel belang, nauw betrekken; ploegleiders veel belang en redelijk veel invloed, nauw betrekken; uitzendbureau veel invloed op de uitvoering maar minder belang, tevreden houden; uitzendkrachten veel belang, weinig invloed, informeren. Weerstand: de baliemedewerker werkt al jaren zo en voelt de verandering als kritiek (gezichtsverlies), aanpak waardering voor het verleden, of verliest de regie over de uitgifte (verlies aan controle), aanpak ruimte geven door mee te laten ontwerpen (Catchball). Ploegleiders moeten maten vooraf aanleveren, dat kost eerst meer werk, aanpak tijd vrijmaken.",
   ["Minstens vijf stakeholders, inclusief rimpeleffect", "Vier juist geplaatst met aanpak", "Twee keer weerstand met oorzaak en passende aanpak"])
op("ppe2-o4", W, PR, "Logistiek Centrum Noordhaven. Je presenteert je advies aan de directeur operations, die vooral let op het aantal veiligheidsincidenten en op de kosten. Hoe sluit je aan op deze ontvanger? Gebruik de vragen uit de training en geef twee voorbeelden van hoe je visualiseert.",
   "Vragen over de ontvanger: wat weet de directeur al (bijvoorbeeld de klachten van ploegleiders, maar niet de cijfers), wat zijn de belangen (veiligheid, continuïteit van de ploegen, kosten), wat heeft de directeur nodig (wie beslist over het budget voor avondopenstelling; focus op financiën en argumenten) en wat wil de directeur? Denk vanuit de beslisser: wat is nodig om ja te zeggen? Laat dus zien dat 1 op de 6 nu zonder veiligheidsschoenen begint en wat de oplossing kost en oplevert (minder omruilingen, 2 uur per dag minder zoeken en overtypen). Visualiseren: show, don't tell, bijvoorbeeld het huidige proces als swimlane met de knelpunten gemarkeerd, en een eenvoudige grafiek van de wachttijd vóór en na de pilot. Eén boodschap per slide, geen lange teksten: een adviespresentatie is geen rapport.",
   ["Minstens drie vragen over de ontvanger toegepast", "Denken vanuit de beslisser met veiligheid én kosten", "Twee passende visualisaties"])

# ---------- casus ----------
cs("ppe2-c1", W, P, "Logistiek Centrum Noordhaven, deel 1: kiezen en invoeren",
   CASUS + " " + OPTIES + " Het team zet de opties in een PUGH-matrix met de huidige situatie als baseline. Criteria en gewicht: veiligheid 5, wachttijd 4, invoeringskosten 3, werkdruk balie 3. Optie A scoort +2, +2, −2, +1. Optie B scoort +2, +1, −1, +1.",
   [("Bereken de gewogen totalen van A en B. Wat adviseer je, en wat bedoelt de les met 'de matrix is een hulpmiddel, geen rechter'?",
     "A: (2 × 5) + (2 × 4) + (−2 × 3) + (1 × 3) = 10 + 8 − 6 + 3 = 15. B: (2 × 5) + (1 × 4) + (−1 × 3) + (1 × 3) = 10 + 4 − 3 + 3 = 14. Het verschil is klein, dus de score beslist niet vanzelf. Kijk ook naar risico (B is eenvoudiger) en aansluiting op de context (werkt de koppeling met het HR-systeem?). Een onderbouwde keuze voor B is goed te verdedigen, mits je het uitlegt. De matrix maakt de afweging transparant en voedt het gesprek; de waarde zit in die transparantie, niet in het getal. De gewichten spreek je vóór het scoren af.",
     ["Beide totalen juist (15 en 14)", "Advies met argument buiten de score", "Uitleg 'hulpmiddel, geen rechter'"]),
    ("Het team werkt optie B uit en vindt drie risico's: (1) het uitzendbureau geeft een verkeerde maat door (E3, K4, D4); (2) een startpakket ligt niet klaar bij de start van de nachtdienst (E5, K2, D2); (3) een uitgifte wordt niet geregistreerd (E2, K3, D5). Bereken de RPN's, kies het toprisico en bedenk een maatregel met een verantwoordelijke. Welke score daalt?",
     "RPN 1: 3 × 4 × 4 = 48. RPN 2: 5 × 2 × 2 = 20. RPN 3: 2 × 3 × 5 = 30. Toprisico: de verkeerde maat (48), hoewel risico 2 de hoogste ernst heeft. Het gaat om de combinatie van ernst, kans en detectie. Maatregel, bijvoorbeeld: het uitzendbureau gebruikt een vaste maattabel en de ploegleider laat de schoenen bij de start passen, met een reservevoorraad standaardmaten (kans en detectie dalen). Verantwoordelijke: bijvoorbeeld de planner van het uitzendbureau voor de maattabel en de ploegleider voor de pascontrole. Na de maatregel scoor je opnieuw op kans en detectie; de ernst blijft meestal gelijk.",
     ["Drie RPN's juist", "Toprisico juist gekozen met uitleg", "Maatregel met verantwoordelijke", "Juist aangegeven welke score daalt"]),
    ("Kies en onderbouw een invoeringsstrategie met de drie leidende criteria uit de notities, en noem drie randvoorwaarden voor een goede pilot.",
     "Leidende criteria: het risico voor de operationele dienstverlening (de ploegen moeten blijven draaien en veilig werken), de mogelijkheid tot schaduwdraaien (het papieren formulier kan tijdelijk blijven) en de technische mogelijkheid om te faseren (per ploeg kan goed). Keuze, bijvoorbeeld: een pilot in de nachtploeg, omdat daar het probleem het grootst is, daarna gefaseerd naar avond- en dagploeg. Big-bang heeft het hoogste risico. Randvoorwaarden: een plan (doel, duur, betrokkenen), een datacollectieplan (wie meet wachttijd en omruilingen, hoe vaak), communicatie aan ploegleiders, uitzendbureau en uitzendkrachten, training van balie en ploegleiders, uitvoering volgens plan en evaluatie tegen de succescriteria.",
     ["Drie criteria toegepast op de casus", "Strategie passend gekozen en onderbouwd", "Drie randvoorwaarden voor de pilot"])])
cs("ppe2-c2", W, P, "Logistiek Centrum Noordhaven, deel 2: borgen en overdragen",
   "De pilot met startpakketten in de nachtploeg is geslaagd: de wachttijd daalde van 2,5 werkdagen naar een halve dag en 96% van de nieuwe uitzendkrachten had vóór de eerste dienst complete PBM. Noordhaven rolt gefaseerd uit naar de avond- en dagploeg. De teamleider Facilitaire Services wordt proceseigenaar; de directeur operations is sponsor. Het studentteam vertrekt over drie weken. Nog open: de afspraak met het uitzendbureau over het doorgeven van maten staat nog niet in het contract, en de avondopenstelling van de balie wacht op een besluit over extra uren.",
   [("Werk het borgingsplan uit met de zes bouwstenen.",
     "Standaardisatie: een SOP voor het klaarzetten en uitgeven van startpakketten (afbakening, KPI's en voorschriften, volgorde van stappen, vastleggen), plus visueel management: gelabelde vakken per maat en een lijst per ploeg. KPI-opvolging: percentage nieuwe uitzendkrachten met complete PBM vóór de eerste dienst, norm minstens 95%, ingrijpen onder 90%; en percentage omruilingen, norm maximaal 8%. Vast ritme: wekelijks in de ploegoverdracht, maandelijks in het teamoverleg. Eigenaarschap: de teamleider Facilitaire Services, met naam, die het ook weet. Evaluatiemomenten: maandelijks Check en Act; presteert het goed, dan de standaard bijwerken, anders een nieuwe verbeterronde. Overdracht: een dossier met SOP, KPI-definities, eigenaarschap en evaluatie-afspraken, actief toegelicht. Lessons learned: bijvoorbeeld 'betrek het uitzendbureau vanaf de start'.",
     ["Standaardisatie met SOP of visueel management", "KPI met norm, ingrijpgrens en ritme", "Eigenaar met naam of rol", "Evaluatie (PDCA), overdracht en lessons learned concreet"]),
    ("Het team wil op de laatste dag het dossier mailen en daarna vertrekken. Wat adviseer je? Noem wat er in het overdrachtsdossier hoort, wie je uitnodigt voor de Tollgate en welke losse eindjes je expliciet benoemt.",
     "Niet zomaar mailen: overdracht is een geplande activiteit, en volgens de gouden regel draag je pas over als de proceseigenaar het echt kan dragen; daarna pas ontbind je het team. Dossier: werkstandaard (SOP of EPL), borgingsplan (KPI's, normen, evaluatieritme), eigenaarschap (teamleider Facilitaire Services, met afspraken), projectdocumentatie (analyse, current en future state) en losse eindjes plus lessons learned. Tollgate met de directeur operations (sponsor), de teamleider Facilitaire Services, de baliemedewerker, een vertegenwoordiging van de ploegleiders en eventueel het uitzendbureau. Agenda: storyboard, wat ging goed en wat fout, toetsen aan de succescriteria (96% compleet, wachttijd een halve dag) en formeel overdragen. Losse eindjes: de maatafspraak in het contract met het uitzendbureau en het besluit over de avondopenstelling. Daarna verankeren en archiveren (Lean Back: de organisatie blijft eigenaar).",
     ["Mailen afgewezen met de gouden regel", "Inhoud van het dossier", "Tollgate met deelnemers en agenda", "Beide losse eindjes benoemd"]),
    ("Formuleer twee lessons learned en één retro-uitkomst die het team kan vastleggen. Leg het verschil uit en zeg voor wie de lessen waardevol zijn.",
     "Lessons learned gaan over de aanpak, bijvoorbeeld: 'Betrek het uitzendbureau vanaf de eerste week, want daar begint de maatinformatie.' 'Test de werkwijze eerst in de nachtploeg, waar het knelpunt het grootst is, en meet vooraf de wachttijd.' Of de aanname die niet klopte: 'We dachten dat ploegleiders de maten wisten; dat bleek niet zo.' Een retro-uitkomst gaat over de samenwerking in het team, bijvoorbeeld: 'We spraken te laat af wie het contact met de opdrachtgever onderhield.' Waardevol voor de opdrachtgever (verbetert verder), het volgende team (vermijdt valkuilen) en jezelf (reflectie en transfer naar stage). Een les als 'betrek het uitzendbureau vanaf het begin' is herbruikbaar, dus een kandidaat voor best practice. Geen dooddoeners: elke les zegt wat je voortaan doet.",
     ["Twee concrete lessons over de aanpak", "Eén retro-uitkomst over de samenwerking", "Verschil en voor wie waardevol"])])
